body {
  -webkit-font-smoothing: antialiased; /* For macOS/iOS */
  -moz-osx-font-smoothing: grayscale; /* For macOS/iOS */
  text-rendering: optimizeLegibility; /* General enhancement for quality */
  font-smoothing: antialiased; /* Future-proofing for standard */
}

/* For specific large headlines where precision is key (use with caution due to performance) */
h1 {
  text-rendering: geometricPrecision;
}

/* For performance-critical interactive elements where speed matters most */
.interactive-button-text {
  text-rendering: optimizeSpeed;
}
